"""搜索预处理工具。"""


def normalize_keyword(keyword: str) -> str:
    """规范化搜索关键词：去除首尾空白。"""
    return keyword.strip()

"""用户意图识别（chat / task / file / memory / ...）。

贴近 MfkAgent IntentAnalyzer：用正则规则做确定性分类，
结果仅作为「工具建议」软提示，不做硬 gate。
"""
import re
from typing import Dict


class IntentAnalyzer:
    """两层意图分析：事实需求 → 动作意图。"""

    def __init__(self):
        self._factual_patterns = [
            (
                "file_operation",
                [
                    r"文件.*内容", r"文件.*存在", r"文件.*在哪",
                    r"读取.*文件", r"查看.*文件", r"分析.*代码",
                    r"这个文件", r"那个文件", r"哪个文件",
                ],
            ),
            (
                "project_debug",
                [
                    r"为什么.*报错", r"为什么.*失败", r"修复.*bug",
                    r"测试.*失败", r"运行.*失败", r"调试.*代码",
                ],
            ),
            (
                "memory",
                [
                    r"记住.*", r"记得.*", r"我之前.*说过", r"上次.*提到",
                ],
            ),
        ]

        self._action_patterns = [
            (
                "file_operation",
                [
                    r"创建.*文件", r"修改.*文件", r"删除.*文件",
                    r"列出.*目录", r"写.*文件",
                ],
            ),
            (
                "project_debug",
                [
                    r"调试.*代码", r"修复.*错误", r"解决.*问题", r"跑.*测试",
                ],
            ),
            (
                "memory_operation",
                [
                    r"记住.*", r"保存.*记忆", r"添加.*记忆", r"以后.*记得",
                ],
            ),
        ]

    def analyze(self, message: str) -> Dict:
        """返回 {"suggest_tools": bool, "intent": str, "layer": str, "confidence": float}"""
        msg = (message or "").lower().strip()
        if not msg:
            return {"suggest_tools": False, "intent": "general_chat", "layer": "empty", "confidence": 1.0}

        for intent, patterns in self._factual_patterns:
            for p in patterns:
                if re.search(p, msg):
                    return {"suggest_tools": True, "intent": intent, "layer": "factual_need", "confidence": 0.9}

        for intent, patterns in self._action_patterns:
            for p in patterns:
                if re.search(p, msg):
                    return {"suggest_tools": True, "intent": intent, "layer": "action_intent", "confidence": 0.85}

        return {"suggest_tools": False, "intent": "general_chat", "layer": "self_check", "confidence": 0.5}

"""FastAPI 应用入口。"""

from fastapi import FastAPI

from app.database import get_engine
from app.models import Base
from app.api import agents, chats, memories

app = FastAPI(title="MFKChat", version="1.0.0")


@app.on_event("startup")
def on_startup() -> None:
    Base.metadata.create_all(bind=get_engine())


app.include_router(agents.router)
app.include_router(chats.router)
app.include_router(memories.router)


@app.get("/health")
def health() -> dict:
    return {"status": "ok"}

"""记忆路由。"""
from fastapi import APIRouter, HTTPException, Depends, Query
from typing import List

from app.database import Session, create_session
from app.models import MemoryItem
from app.schemas import MemoryCreate, MemoryOut
from app.core import memory as memory_mod
from app.core.search import normalize_keyword

router = APIRouter(prefix="/memories", tags=["memories"])


def get_db():
    db = create_session()
    try:
        yield db
    finally:
        db.close()


@router.post("", response_model=MemoryOut)
def add_memory(body: MemoryCreate, db: Session = Depends(get_db)):
    if body.scope not in ("global", "agent", "project"):
        raise HTTPException(400, "scope 必须为 global/agent/project")
    if not body.content.strip():
        raise HTTPException(400, "内容不能为空")
    item = memory_mod.add_memory(db, body.scope, body.content, body.agent_id, body.source)
    db.commit()
    db.refresh(item)
    return item


@router.get("", response_model=List[MemoryOut])
def list_memories(scope: str = None, agent_id: str = None,
                  limit: int = 30, db: Session = Depends(get_db)):
    items = memory_mod.query_memories(db, scope, agent_id, limit)
    return items


@router.get("/search", response_model=List[MemoryOut])
def search_memories(q: str = Query(..., min_length=1), db: Session = Depends(get_db)):
    keyword = normalize_keyword(q)
    items = db.query(MemoryItem).filter(
        MemoryItem.content.ilike(f"%{keyword}%")
    ).order_by(MemoryItem.created_at.desc()).all()
    return items


@router.delete("/{memory_id}")
def delete_memory(memory_id: int, db: Session = Depends(get_db)):
    item = db.query(MemoryItem).filter(MemoryItem.id == memory_id).first()
    if item is None:
        raise HTTPException(404, "记忆不存在")
    db.delete(item)
    db.commit()
    return {"status": "deleted"}

